{"term": "konsomatris", "lang": "tr", "script": "latin", "romanization": null, "category": "sex_work_pornography", "subcategory": "hostess_entertainment", "concept": "demimonde", "is_novel_concept": false, "register": "loanword", "crude": 40, "technical": 20, "recognition_pct_current": 70, "recognition_pct_peak": 70, "peak_year": null, "regional": null, "definition": "A female hostess employed in a Turkish pavyon (nightclub/entertainment venue) to sit with male customers and encourage alcohol consumption; sexual availability is commonly implied but varies by establishment.", "english_term": "bar hostess / consommatrice", "english_translation_quality": "approximate", "notes": "Borrowed from French 'consommatrice' (female consumer); occupies a legal gray zone between entertainer and sex worker in Turkish nightlife. Specific to the pavyon entertainment culture; not a direct synonym for prostitute but heavily associated with it in public perception."}
{"term": "bar kızı", "lang": "tr", "script": "latin", "romanization": null, "category": "sex_work_pornography", "subcategory": "bar_girl", "concept": "sex_worker_archaic", "is_novel_concept": false, "register": "slang_neutral", "crude": 50, "technical": 10, "recognition_pct_current": 92, "recognition_pct_peak": 92, "peak_year": null, "regional": null, "definition": "Literally 'bar girl'; a woman working in a bar or nightclub whose role implies sexual availability, ranging from hostess and companion to explicit sex worker depending on the establishment.", "english_term": "bar girl", "english_translation_quality": "direct", "notes": "'Kız' (girl) carries a mildly diminutive tone and can imply youth; the term is descriptive rather than purely pejorative. The degree of implied prostitution is context-dependent; contrast with the more institutionally specific 'konsomatris' and 'pavyon kızı'."}
